    /**
     * Method to retrieve the Building via BuildingFetchOneSummary
     * @param 	summary BuildingFetchOneSummary 
     * @return 	BuildingFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Building getBuilding( BuildingFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "BuildingFetchOneSummary arg cannot be null" );
    	
    	Building entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Building
        	// --------------------------------------
        	CompletableFuture<Building> futureEntity = queryGateway.query(new FindBuildingQuery( new LoadBuildingFilter( summary.getBuildingId() ) ), ResponseTypes.instanceOf(Building.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Building with id " + summary.getBuildingId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


